inputs.code:
{
    // Control inputs
    play: {
      group: 'Controls',
      type: 'signal',
      displayName: 'Play',
      valueChangedToTrue: function() {
        this._playAnimation();
      }
    },
    pause: {
      group: 'Controls',
      type: 'signal',
      displayName: 'Pause',
      valueChangedToTrue: function() {
        this._pauseAnimation();
      }
    },
    stop: {
      group: 'Controls',
      type: 'signal',
      displayName: 'Stop',
      valueChangedToTrue: function() {
        this._stopAnimation();
      }
    },
    reverse: {
      group: 'Controls',
      type: 'signal',
      displayName: 'Reverse',
      valueChangedToTrue: function() {
        this._reverseAnimation();
      }
    },
    progress: {
      group: 'Controls',
      type: 'number',
      displayName: 'Set Progress (0-1)',
      set: function(value) {
        this._setProgress(Math.max(0, Math.min(1, value)));
      }
    }
  }

